-- System simulation of the first-light build: the real core (psx_top_pocket_flat: no SPU, no CD, no MDEC), the shell's
-- vram_adapter, ram_adapter and video_fl, and behavioural PSRAM/SDRAM request ports with the BIOS preloaded. Writes every
-- frame the APF would get as out/frame_<n>.ppm and reports the bus activity. Generated by gen_tb.py; run.sh runs it.
-- docs/pocket/POCKET_TOP.md, "First light".
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity tb_system is
   generic (BIOS_FILE : string := "psxbios.bin"; RUN_MS : natural := 100);
end entity;

architecture sim of tb_system is
   constant T : time := 1230229 fs;  -- 1 / 812.8512 MHz: every clock is a whole number of VCO periods
   signal clk1x, clk2x, clk3x, clk_sys, clk_vid : std_logic := '0';
   signal reset, rst_mem : std_logic := '1';

   signal c_isPaused : std_logic;
   signal c_pause : std_logic;
   signal c_hps_busy : std_logic;
   signal c_loadExe : std_logic;
   signal c_exe_initial_pc : std_logic_vector(31 downto 0);
   signal c_exe_initial_gp : std_logic_vector(31 downto 0);
   signal c_exe_load_address : std_logic_vector(31 downto 0);
   signal c_exe_file_size : std_logic_vector(31 downto 0);
   signal c_exe_stackpointer : std_logic_vector(31 downto 0);
   signal c_fastboot : std_logic;
   signal c_ram8mb : std_logic;
   signal c_TURBO_MEM : std_logic;
   signal c_TURBO_COMP : std_logic;
   signal c_TURBO_CACHE : std_logic;
   signal c_TURBO_CACHE50 : std_logic;
   signal c_REPRODUCIBLEGPUTIMING : std_logic;
   signal c_INSTANTSEEK : std_logic;
