   signal c_LIMITREADSPEED : std_logic;
   signal c_IGNORECDDMATIMING : std_logic;
   signal c_ditherOff : std_logic;
   signal c_interlaced480pHack : std_logic;
   signal c_showGunCrosshairs : std_logic;
   signal c_enableNeGconRumble : std_logic;
   signal c_fpscountOn : std_logic;
   signal c_cdslowOn : std_logic;
   signal c_testSeek : std_logic;
   signal c_pauseOnCDSlow : std_logic;
   signal c_errorOn : std_logic;
   signal c_LBAOn : std_logic;
   signal c_PATCHSERIAL : std_logic;
   signal c_noTexture : std_logic;
   signal c_textureFilter : std_logic_vector(1 downto 0);
   signal c_textureFilterStrength : std_logic_vector(1 downto 0);
   signal c_textureFilter2DOff : std_logic;
   signal c_dither24 : std_logic;
   signal c_render24 : std_logic;
   signal c_drawSlow : std_logic;
   signal c_syncVideoOut : std_logic;
   signal c_syncInterlace : std_logic;
   signal c_rotate180 : std_logic;
   signal c_fixedVBlank : std_logic;
   signal c_vCrop : std_logic_vector(1 downto 0);
