   signal c_SPUon : std_logic;
   signal c_SPUIRQTrigger : std_logic;
   signal c_SPUSDRAM : std_logic;
   signal c_REVERBOFF : std_logic;
   signal c_REPRODUCIBLESPUDMA : std_logic;
   signal c_WIDESCREEN : std_logic_vector(1 downto 0);
   signal c_oldGPU : std_logic;
   signal c_biosregion : std_logic_vector(1 downto 0);
   signal c_ram_refresh : std_logic;
   signal c_ram_dataWrite : std_logic_vector(31 downto 0);
   signal c_ram_dataRead32 : std_logic_vector(31 downto 0);
   signal c_ram_Adr : std_logic_vector(24 downto 0);
   signal c_ram_cntDMA : std_logic_vector(1 downto 0);
   signal c_ram_be : std_logic_vector(3 downto 0);
   signal c_ram_rnw : std_logic;
