   signal c_cd_hps_lba_sim : std_logic_vector(31 downto 0);
   signal c_cd_hps_ack : std_logic;
   signal c_cd_hps_write : std_logic;
   signal c_cd_hps_data : std_logic_vector(15 downto 0);
   signal c_spuram_dataWrite : std_logic_vector(31 downto 0);
   signal c_spuram_Adr : std_logic_vector(18 downto 0);
   signal c_spuram_be : std_logic_vector(3 downto 0);
   signal c_spuram_rnw : std_logic;
   signal c_spuram_ena : std_logic;
   signal c_spuram_dataRead : std_logic_vector(31 downto 0);
   signal c_spuram_done : std_logic;
   signal c_memcard_changed : std_logic;
   signal c_saving_memcard : std_logic;
   signal c_memcard1_load : std_logic;
   signal c_memcard2_load : std_logic;
   signal c_memcard_save : std_logic;
   signal c_memcard1_mounted : std_logic;
   signal c_memcard1_available : std_logic;
   signal c_memcard1_rd : std_logic;
   signal c_memcard1_wr : std_logic;
   signal c_memcard1_lba : std_logic_vector(6 downto 0);
   signal c_memcard1_ack : std_logic;
   signal c_memcard1_write : std_logic;
   signal c_memcard1_addr : std_logic_vector(8 downto 0);
   signal c_memcard1_dataIn : std_logic_vector(15 downto 0);
   signal c_memcard1_dataOut : std_logic_vector(15 downto 0);
   signal c_memcard2_mounted : std_logic;
   signal c_memcard2_available : std_logic;
   signal c_memcard2_rd : std_logic;
   signal c_memcard2_wr : std_logic;
