   signal c_memcard2_ack : std_logic;
   signal c_memcard2_write : std_logic;
   signal c_memcard2_addr : std_logic_vector(8 downto 0);
   signal c_memcard2_dataIn : std_logic_vector(15 downto 0);
   signal c_memcard2_dataOut : std_logic_vector(15 downto 0);
   signal c_videoout_on : std_logic;
   signal c_isPal : std_logic;
   signal c_pal60 : std_logic;
   signal c_hsync : std_logic;
   signal c_vsync : std_logic;
   signal c_hblank : std_logic;
   signal c_vblank : std_logic;
   signal c_DisplayWidth : std_logic_vector(10 downto 0);
   signal c_DisplayHeight : std_logic_vector(9 downto 0);
   signal c_DisplayOffsetX : std_logic_vector(9 downto 0);
   signal c_DisplayOffsetY : std_logic_vector(8 downto 0);
   signal c_video_ce : std_logic;
   signal c_video_interlace : std_logic;
   signal c_video_r : std_logic_vector(7 downto 0);
   signal c_video_g : std_logic_vector(7 downto 0);
   signal c_video_b : std_logic_vector(7 downto 0);
   signal c_video_isPal : std_logic;
   signal c_video_fbmode : std_logic;
