   signal c_video_hResMode : std_logic_vector(2 downto 0);
   signal c_video_frameindex : std_logic_vector(3 downto 0);
   signal c_DSAltSwitchMode : std_logic;
   signal c_joypad1 : std_logic_vector(59 downto 0);
   signal c_joypad2 : std_logic_vector(59 downto 0);
   signal c_joypad3 : std_logic_vector(59 downto 0);
   signal c_joypad4 : std_logic_vector(59 downto 0);
   signal c_multitap : std_logic;
   signal c_multitapDigital : std_logic;
   signal c_multitapAnalog : std_logic;
   signal c_neGconRumble : std_logic;
   signal c_joypad1_rumble : std_logic_vector(15 downto 0);
   signal c_joypad2_rumble : std_logic_vector(15 downto 0);
   signal c_joypad3_rumble : std_logic_vector(15 downto 0);
   signal c_joypad4_rumble : std_logic_vector(15 downto 0);
   signal c_padMode : std_logic_vector(1 downto 0);
   signal c_MouseEvent : std_logic;
   signal c_MouseLeft : std_logic;
   signal c_MouseRight : std_logic;
   signal c_MouseX : std_logic_vector(8 downto 0);
   signal c_MouseY : std_logic_vector(8 downto 0);
   signal c_snacPort1 : std_logic;
   signal c_snacPort2 : std_logic;
   signal c_irq10Snac : std_logic;
   signal c_actionNextSnac : std_logic;
   signal c_receiveValidSnac : std_logic;
   signal c_ackSnac : std_logic;
