   signal c_sound_out_right : std_logic_vector(15 downto 0);
   signal c_increaseSSHeaderCount : std_logic;
   signal c_save_state : std_logic;
   signal c_load_state : std_logic;
   signal c_savestate_number : std_logic_vector(1 downto 0);
   signal c_state_loaded : std_logic;
