   c_dither24 <= '0';
   c_render24 <= '0';
   c_drawSlow <= '0';
   c_syncVideoOut <= '1';
   c_syncInterlace <= '0';
   c_rotate180 <= '0';
   c_fixedVBlank <= '0';
   c_vCrop <= (others => '0');
   c_hCrop <= '0';
   c_SPUon <= '0';
   c_SPUIRQTrigger <= '0';
   c_SPUSDRAM <= '1';
   c_REVERBOFF <= '1';
   c_REPRODUCIBLESPUDMA <= '0';
   c_WIDESCREEN <= (others => '0');
   c_oldGPU <= '0';
   c_biosregion <= (others => '0');
   c_region <= (others => '0');
   c_hasCD <= '0';
   c_fastCD <= '0';
   c_LIDopen <= '1';
   c_trackinfo_data <= (others => '0');
   c_trackinfo_addr <= (others => '0');
   c_trackinfo_write <= '0';
   c_cd_hps_ack <= '0';
   c_cd_hps_write <= '0';
   c_cd_hps_data <= (others => '0');
   c_spuram_dataRead <= (others => '0');
   c_spuram_done <= '0';
   c_memcard1_load <= '0';
   c_memcard2_load <= '0';
   c_memcard_save <= '0';
   c_memcard1_mounted <= '0';
   c_memcard1_available <= '0';
   c_memcard1_ack <= '0';
   c_memcard1_write <= '0';
   c_memcard1_addr <= (others => '0');
   c_memcard1_dataIn <= (others => '0');
   c_memcard2_mounted <= '0';
   c_memcard2_available <= '0';
   c_memcard2_ack <= '0';
   c_memcard2_write <= '0';
   c_memcard2_addr <= (others => '0');
